export interface ViewerNavigation {
  offset: number;
  page: number;
  detail: boolean;
  first: boolean;
  previous: boolean;
  next: boolean;
}
export type ViewerNavigationAction =
  | { type: 'local' | 'sort' | 'code' | 'cards' }
  | { type: 'detail'; index: number }
  | { type: 'page'; direction: -1 | 0 | 1 };

